/** Try the live API, fall back to the static snapshot in /public/data. */ async function liveOrStatic(apiPath, staticPath) {
    try {
        return {
            data: await getJson(`${API_URL}${apiPath}`),
            source: "live"
        };
    } catch  {
        return {
            data: await getJson(staticPath, 10000),
            source: "static"
        };
    }
}
